import { quotation_sub_categories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    categoriessubEddition: Boolean,
    categoriesItem: Object,
    rowInfo: Object
  },
  data() {
    return {
      categoriesName: "",
      categoriestax: "",
      categoriesPrice: "",
      categoryitems: [],
      maincategories: "",
      loading: false,
      categoriesdescription: "",
      depreciationitems: Array.from({
        length: 100
      }, (_, i) => i + 1)
    };
  },
  watch: {
    categoriessubEddition: {
      async handler() {
        if (this.categoriessubEddition == true) {
          this.categoriesName = this.categoriesItem.text;
          this.categoriestax = this.categoriesItem.sub_category_tax;
          this.categoriesPrice = this.categoriesItem.sub_category_price;
        }
      },
      immediate: true
    }
  },
  methods: {
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    process(event) {
      if (event.type == "paste") {
        var clipboardData = event.clipboardData || window.clipboardData;
        var pastedData = clipboardData.getData("Text");
        if (isNaN(pastedData)) {
          event.preventDefault();
        } else {
          return;
        }
      }
      var keyCode = event.keyCode || event.which;
      if (keyCode >= 96 && keyCode <= 105) {
        keyCode -= 48;
      }
      var charValue = String.fromCharCode(keyCode);
      if (isNaN(parseInt(charValue)) && event.keyCode != 8) {
        event.preventDefault();
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(quotation_sub_categories, {
          input: {
            category_id: this.rowInfo.category_id,
            sub_category_name: this.categoriesName,
            sub_category_id: this.categoriesItem.value,
            sub_category_price: this.categoriesPrice,
            sub_category_tax: this.categoriestax,
            action_type: "UPDATE"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.quotation_sub_categories);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
